def transform(grid):
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])

    # Find the background color (most frequent value)
    from collections import Counter
    all_values = Counter(val for row in grid for val in row)
    if not all_values:
        return grid
    background = max(all_values.keys(), key=lambda x: all_values[x])

    # Find all non-background cells
    non_bg_positions = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] != background]

    if not non_bg_positions:
        return grid

    # Find the main special value (most common among non-background)
    special_counts = Counter()
    for r, c in non_bg_positions:
        special_counts[grid[r][c]] += 1
    main_special = special_counts.most_common()[0][0]

    # Find all cells with the main special value
    main_special_cells = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == main_special:
                main_special_cells.add((r, c))

    # Build connected components of main_special cells
    visited = set()

    def bfs(start):
        component = set()
        queue = [start]
        visited.add(start)
        component.add(start)
        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == main_special and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        component.add((nr, nc))
                        queue.append((nr, nc))
        return component

    components = []
    for r, c in main_special_cells:
        if (r, c) not in visited:
            comp = bfs((r, c))
            components.append(comp)

    # Create output grid and mark border cells
    output = [row[:] for row in grid]
    for component in components:
        for r, c in component:
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == background:
                        output[nr][nc] = 1

    return output
