def transform(grid):
    if not grid:
        return []

    from collections import Counter
    rows, cols = len(grid), len(grid[0])

    # Find background color (most frequent)
    all_values = Counter(val for row in grid for val in row)
    background = max(all_values.keys(), key=lambda x: all_values[x])

    # Find special value (most common non-background)
    non_bg_vals = [grid[r][c] for r in range(rows) for c in range(cols) if grid[r][c] != background]
    if not non_bg_vals:
        return grid
    main_special = Counter(non_bg_vals).most_common(1)[0][0]

    # Find all special cells
    special_cells = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == main_special:
                special_cells.add((r, c))

    # Create output and mark 8 neighbors of each special cell with 1
    output = [row[:] for row in grid]
    for r, c in special_cells:
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == background:
                        output[nr][nc] = 1

    return output
